describe("SPEC-RPC-002: Share one spec host per spec file", () => {
  let h: Harness;
  beforeAll(async () => {
    h = await createHarness({ configPath: CONFIG_PATH, specPath: SPEC_PATH });
  });
  afterAll(async () => {
    await h.teardown();
  });
  for (const c of CASES) {
    it(c.name, async () => {
      await h.runCase(c, INLINE);
    });
  }
});
